function validateConfiguration(input, nowIso) {
  const cfg = input.setup;
  if (!cfg || typeof cfg !== 'object') throw new Error('Open Configuration and complete the nonsecret setup fields.');
  const target = typeof cfg.target_domain === 'string' ? cfg.target_domain.trim().toLowerCase().replace(/\.$/, '').replace(/^www\./, '') : '';
  if (!target || target.length > 253 || !target.includes('.') || !target.split('.').every(label => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label))) throw new Error('Set target_domain to an ASCII hostname such as example.com, without a scheme, port, path or credentials. Use punycode for internationalized hostnames.');
  const raw = Array.isArray(cfg.keywords) ? cfg.keywords : typeof cfg.keywords === 'string' ? cfg.keywords.split(',') : [];
  const keywords = [], seen = new Set();
  for (const value of raw) {
    if (typeof value !== 'string') throw new Error('Every keyword must be text.');
    const keyword = value.trim().replace(/\s+/g, ' ');
    if (!keyword || keyword.length > 100 || /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(keyword)) throw new Error('Use nonempty keywords of at most 100 characters.');
    const key = keyword.toLowerCase();
    if (!seen.has(key)) { seen.add(key); keywords.push(keyword); }
  }
  if (!keywords.length || keywords.length > 10) throw new Error('Configure between 1 and 10 unique keywords per snapshot.');
  const country_code = String(cfg.country_code || '').trim().toLowerCase();
  const language_code = String(cfg.language_code || '').trim().toLowerCase();
  if (!/^[a-z]{2}$/.test(country_code) || !/^[a-z]{2}$/.test(language_code)) throw new Error('Use two-letter country_code and language_code values supported by the Apify actor.');
  const results_per_keyword = Number(cfg.results_per_keyword);
  if (!Number.isInteger(results_per_keyword) || results_per_keyword < 1 || results_per_keyword > 50) throw new Error('results_per_keyword must be an integer between 1 and 50.');
  const report_email = typeof cfg.report_email === 'string' ? cfg.report_email.trim() : '';
  if (!/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?\.[A-Za-z]{2,63}$/.test(report_email) || report_email.length > 254) throw new Error('Set report_email to one recipient email address. Lists and line breaks are not accepted.');
  if (typeof cfg.spreadsheet_id !== 'string' || !/^[A-Za-z0-9_-]{20,150}$/.test(cfg.spreadsheet_id)) throw new Error('Set spreadsheet_id to your Google spreadsheet ID.');
  if (typeof cfg.sheet_name !== 'string' || !cfg.sheet_name.trim() || cfg.sheet_name.length > 80 || /[\[\]:*?/\\\u0000-\u001f]/.test(cfg.sheet_name)) throw new Error('Set sheet_name to an existing Google Sheets tab name, such as Rankings.');
  if (typeof cfg.openai_model !== 'string' || !cfg.openai_model.trim() || cfg.openai_model.length > 100 || /[\s\u0000]/.test(cfg.openai_model)) throw new Error('Choose a currently available OpenAI chat model in openai_model.');
  if (typeof nowIso !== 'string' || !Number.isFinite(Date.parse(nowIso))) throw new Error('A valid snapshot timestamp is required.');
  return { target_domain: target, keywords, country_code, language_code, results_per_keyword, report_email, spreadsheet_id:cfg.spreadsheet_id, sheet_name:cfg.sheet_name.trim(), openai_model:cfg.openai_model.trim(), checked_at: new Date(nowIso).toISOString() };
}
return [{json:validateConfiguration($input.first().json,new Date().toISOString())}];

function parsePublicResultUrl(value) {
  if (typeof value !== 'string' || value.length > 2048 || /[\u0000-\u0020\u007f\\]/.test(value)) return null;
  const match = value.match(/^https?:\/\/([^/?#]+)(?:[/?#].*)?$/i);
  if (!match || match[1].includes('@')) return null;
  const authority = match[1].match(/^([a-z0-9.-]+)(?::([0-9]{1,5}))?$/i);
  if (!authority || (authority[2] && (+authority[2] < 1 || +authority[2] > 65535))) return null;
  const host = authority[1].toLowerCase().replace(/\.$/, '').replace(/^www\./, '');
  if (host.length > 253 || !host.includes('.') || !host.split('.').every(label => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label))) return null;
  return { url: value, domain: host };
}
function extractRankings(responses, requests, cfg, parseUrl) {
  if (responses.length !== requests.length || requests.length !== cfg.keywords.length) throw new Error('Apify returned an unexpected response count. No report or history rows were produced.');
  const rows = [];
  const text = (v, max) => typeof v === 'string' ? v.replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').slice(0, max) : '';
  for (let i = 0; i < responses.length; i++) {
    const response = responses[i];
    const keyword = requests[i].keyword;
    if (!cfg.keywords.includes(keyword) || response.statusCode !== 200 || !Array.isArray(response.body) || response.body.length > 3) throw new Error(`Invalid Apify dataset response for keyword ${keyword}.`);
    const results = [];
    for (const page of response.body) {
      if (!page || typeof page !== 'object' || !Array.isArray(page.organicResults)) throw new Error(`Apify did not return an organicResults list for ${keyword}. Check actor input, quota and output schema.`);
      if (page.searchQuery && typeof page.searchQuery.term === 'string' && page.searchQuery.term.trim().toLowerCase().replace(/\s+/g, ' ') !== keyword.toLowerCase()) throw new Error(`Apify returned a different query for ${keyword}; refusing to mislabel its rankings.`);
      for (let j = 0; j < Math.min(page.organicResults.length, cfg.results_per_keyword); j++) {
        const r = page.organicResults[j];
        if (!r || typeof r !== 'object') throw new Error(`Malformed SERP result for ${keyword}.`);
        const parsed = parseUrl(r.url);
        if (!parsed) throw new Error(`A SERP result for ${keyword} has an invalid HTTP(S) URL. No misleading report was sent.`);
        const rank = r.position === undefined || r.position === null ? j + 1 : Number(r.position);
        if (!Number.isInteger(rank) || rank < 1 || rank > cfg.results_per_keyword) throw new Error(`A SERP position for ${keyword} is outside the configured tracked range.`);
        results.push({checked_at:cfg.checked_at, keyword, rank, title:text(r.title,300), url:parsed.url, domain:parsed.domain, description:text(r.description,600), is_target_domain:parsed.domain === cfg.target_domain || parsed.domain.endsWith('.' + cfg.target_domain), result_status:'ranked', tracked_limit:cfg.results_per_keyword});
      }
    }
    const seen = new Set();
    const unique = results.sort((a,b)=>a.rank-b.rank).filter(r => {const key=r.rank+'\n'+r.url;if(seen.has(key))return false;seen.add(key);return true;}).slice(0,cfg.results_per_keyword);
    if (!unique.length) rows.push({checked_at:cfg.checked_at,keyword,rank:null,title:'',url:'',domain:'',description:'',is_target_domain:false,result_status:'no_organic_results',tracked_limit:cfg.results_per_keyword});
    else rows.push(...unique);
  }
  return rows;
}
const cfg=$('Validate setup').first().json;
const requests=$('Prepare keyword requests').all().map(i=>i.json);
return extractRankings($input.all().map(i=>i.json),requests,cfg,parsePublicResultUrl).map(json=>({json}));

function makeAnalysisData(rows, cfg) {
  const summaries = cfg.keywords.map(keyword => {
    const ranked=rows.filter(r=>r.keyword===keyword && r.result_status==='ranked');
    const competitors=[],seen=new Set();
    for(const r of ranked) if(!r.is_target_domain && !seen.has(r.domain)){seen.add(r.domain);competitors.push({domain:r.domain,rank:r.rank,title:r.title});if(competitors.length===3)break;}
    return {keyword,trackedLimit:cfg.results_per_keyword,status:ranked.length?'collected':'no_organic_results',targetPositions:ranked.filter(r=>r.is_target_domain).map(r=>r.rank),competitors};
  });
  return { summaries, analysisInput:JSON.stringify({targetDomain:cfg.target_domain,checkedAt:cfg.checked_at,keywords:summaries}) };
}
const cfg=$('Validate setup').first().json;
const rows=$('Extract and validate rankings').all().map(i=>i.json);
return [{json:makeAnalysisData(rows,cfg)}];

