function renderReport(rows, cfg, ai, makeData) {
  const escape = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const info=makeData(rows,cfg);
  let analysis=null;
  if(ai && !ai.error && typeof ai.text==='string' && ai.text.length<=12000) {
    try {
      const cleaned=ai.text.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
      const parsed=JSON.parse(cleaned);
      if(parsed && typeof parsed.summary==='string' && parsed.summary.trim().length>0 && parsed.summary.length<=1000 && Array.isArray(parsed.opportunities) && parsed.opportunities.length>=1 && parsed.opportunities.length<=5 && parsed.opportunities.every(v=>typeof v==='string' && v.trim().length>0 && v.length<=600)) analysis={summary:parsed.summary,opportunities:parsed.opportunities};
    }catch(_error){}
  }
  let html='<h2>SEO ranking snapshot</h2><p><strong>Target:</strong> '+escape(cfg.target_domain)+'<br><strong>Checked:</strong> '+escape(cfg.checked_at)+'<br><strong>Locale:</strong> '+escape(cfg.country_code)+' / '+escape(cfg.language_code)+'</p>';
  for(const s of info.summaries) {
    html+='<h3>'+escape(s.keyword)+'</h3>';
    if(s.status==='no_organic_results') html+='<p>No organic results were returned. The target position is unknown for this snapshot.</p>';
    else html+='<p>'+ (s.targetPositions.length ? 'Target position'+(s.targetPositions.length>1?'s':'')+': '+s.targetPositions.map(escape).join(', ')+'.' : 'Target not present in the top '+escape(s.trackedLimit)+' collected results.') +'</p>';
    if(s.competitors.length) html+='<p><strong>Leading competitors:</strong> '+s.competitors.map(c=>escape(c.domain)+' (#'+escape(c.rank)+')').join(', ')+'</p>';
    const ranked=rows.filter(r=>r.keyword===s.keyword && r.result_status==='ranked').slice(0,5);
    if(ranked.length) html+='<ol>'+ranked.map(r=>'<li value="'+escape(r.rank)+'"><a href="'+escape(r.url)+'" rel="noopener noreferrer">'+escape(r.title||r.domain)+'</a> <span>('+escape(r.domain)+')</span>'+(r.is_target_domain?' <strong>Target</strong>':'')+'</li>').join('')+'</ol>';
  }
  html+='<h2>AI commentary</h2>';
  if(analysis) html+='<p>'+escape(analysis.summary)+'</p><ul>'+analysis.opportunities.map(v=>'<li>'+escape(v)+'</li>').join('')+'</ul><p>These suggestions are generated from this snapshot and need human judgment. Ranking positions above are computed directly from the collected results.</p>';
  else html+='<p>AI commentary was unavailable or failed output validation. The ranking snapshot above and saved history remain available.</p>';
  html+='<p>Google Sheets contains the full snapshot with all collected rows. Each run appends a new UTC timestamped snapshot, including explicit no-result rows. Absence from the tracked range does not establish absence from Google. This workflow does not change a website or its rankings.</p>';
  if(html.length>90000) throw new Error('The rendered email exceeded the 90000-character limit. Reduce keywords or title lengths.');
  return {subject:'SEO ranking report - '+cfg.checked_at.slice(0,10),html,analysis_status:analysis?'validated':'unavailable',snapshot:cfg.checked_at,logged_rows:rows.length};
}
const cfg=$('Validate setup').first().json;
const rows=$('Extract and validate rankings').all().map(i=>i.json);
return [{json:renderReport(rows,cfg,$input.first().json,makeAnalysisData)}];
